UPDATE transport_requests SET
    title = CASE address
        WHEN 'Brandenburg Gate, Berlin' THEN 'Подключение абонента · Центральный район'
        WHEN 'Alexanderplatz, Berlin' THEN 'Проверка линии · Втузгородок'
        WHEN 'Checkpoint Charlie, Berlin' THEN 'Ремонт оборудования · Центр'
        WHEN 'Potsdamer Platz, Berlin' THEN 'Доставка оборудования · Центр'
        WHEN 'East Side Gallery, Berlin' THEN 'Плановое обслуживание · Восточный район'
        ELSE title END,
    address = CASE address
        WHEN 'Brandenburg Gate, Berlin' THEN 'Екатеринбург, ул. Ленина, 15 — демо-локация'
        WHEN 'Alexanderplatz, Berlin' THEN 'Екатеринбург, ул. Малышева, 36 — демо-локация'
        WHEN 'Checkpoint Charlie, Berlin' THEN 'Екатеринбург, ул. Шейнкмана, 73 — демо-локация'
        WHEN 'Potsdamer Platz, Berlin' THEN 'Екатеринбург, ул. 8 Марта, 45 — демо-локация'
        WHEN 'East Side Gallery, Berlin' THEN 'Екатеринбург, ул. Восточная, 56 — демо-локация'
        ELSE address END,
    latitude = CASE address
        WHEN 'Brandenburg Gate, Berlin' THEN 56.8400
        WHEN 'Alexanderplatz, Berlin' THEN 56.8415
        WHEN 'Checkpoint Charlie, Berlin' THEN 56.8325
        WHEN 'Potsdamer Platz, Berlin' THEN 56.8355
        WHEN 'East Side Gallery, Berlin' THEN 56.8465
        ELSE latitude END,
    longitude = CASE address
        WHEN 'Brandenburg Gate, Berlin' THEN 60.6110
        WHEN 'Alexanderplatz, Berlin' THEN 60.6190
        WHEN 'Checkpoint Charlie, Berlin' THEN 60.5940
        WHEN 'Potsdamer Platz, Berlin' THEN 60.6065
        WHEN 'East Side Gallery, Berlin' THEN 60.6325
        ELSE longitude END
WHERE address IN (
    'Brandenburg Gate, Berlin', 'Alexanderplatz, Berlin', 'Checkpoint Charlie, Berlin',
    'Potsdamer Platz, Berlin', 'East Side Gallery, Berlin'
);

